export const categories = ['Canned goods', 'Dry goods', 'Produce', 'Toiletries'] as const;

export type Category = (typeof categories)[number];

export type PantryItem = {
  id: string;
  name: string;
  category: Category;
  quantity: number;
  /** ISO calendar date, `YYYY-MM-DD`. */
  lastRestocked: string;
};

/** At or below this many on hand, an item reads as low stock. */
export const LOW_STOCK = 10;

export const sampleItems: PantryItem[] = [
  { id: 'black-beans', name: 'Black beans', category: 'Canned goods', quantity: 48, lastRestocked: '2026-10-14' },
  { id: 'tomato-soup', name: 'Tomato soup', category: 'Canned goods', quantity: 8, lastRestocked: '2026-10-02' },
  { id: 'brown-rice', name: 'Brown rice, 2 lb bag', category: 'Dry goods', quantity: 22, lastRestocked: '2026-10-11' },
  { id: 'rolled-oats', name: 'Rolled oats', category: 'Dry goods', quantity: 15, lastRestocked: '2026-10-09' },
  { id: 'apples', name: 'Apples', category: 'Produce', quantity: 36, lastRestocked: '2026-10-16' },
  { id: 'potatoes', name: 'Potatoes, 5 lb bag', category: 'Produce', quantity: 6, lastRestocked: '2026-10-13' },
  { id: 'toothpaste', name: 'Toothpaste', category: 'Toiletries', quantity: 12, lastRestocked: '2026-09-28' },
  { id: 'bar-soap', name: 'Bar soap', category: 'Toiletries', quantity: 4, lastRestocked: '2026-09-21' },
];

const dateFormat = new Intl.DateTimeFormat('en-US', { dateStyle: 'medium', timeZone: 'UTC' });

/** Formats an ISO calendar date the same way on the server and in the browser. */
export function formatDate(isoDate: string) {
  return dateFormat.format(new Date(`${isoDate}T00:00:00Z`));
}

/** Today's local calendar date as `YYYY-MM-DD`. */
export function today() {
  const now = new Date();
  const month = String(now.getMonth() + 1).padStart(2, '0');
  const day = String(now.getDate()).padStart(2, '0');
  return `${now.getFullYear()}-${month}-${day}`;
}
EOF

