import { chromium } from 'playwright-core';
const browser = await chromium.launch({ channel: 'chrome' });
for (const [sys, explicit] of [['dark', 'light'], ['light', 'dark']]) {
  const ctx = await browser.newContext({ viewport: { width: 1280, height: 1000 }, colorScheme: sys });
  const page = await ctx.newPage();
  await page.goto('http://localhost:3123/', { waitUntil: 'networkidle' });
  await page.evaluate((m) => document.documentElement.setAttribute('data-theme', m), explicit);
  await page.waitForTimeout(600);
  const btn = await page.locator('button[type="submit"]').evaluate((el) => getComputedStyle(el).backgroundColor);
  const trigger = page.getByRole('combobox', { name: 'Category' });
  await trigger.focus();
  await page.keyboard.press('Enter');
  await page.waitForTimeout(500);
  const popup = await page.getByRole('listbox').evaluate((el) => {
    const chain = [];
    for (let n = el; n && n !== document.body; n = n.parentElement) {
      const s = getComputedStyle(n);
      chain.push([n.tagName, s.backgroundColor, s.colorScheme]);
    }
    return chain;
  });
  console.log(`system ${sys}, explicit ${explicit}: submit ${btn}; popup chain ${JSON.stringify(popup)}`);
  await page.screenshot({ path: `shots/select-${explicit}.png` });
  await ctx.close();
}
// Reduced motion keeps the collapse values.
const ctx = await browser.newContext({ reducedMotion: 'reduce' });
const page = await ctx.newPage();
await page.goto('http://localhost:3123/', { waitUntil: 'networkidle' });
console.log('reduced motion fast:', await page.evaluate(() => getComputedStyle(document.documentElement).getPropertyValue('--ult-motion-fast')));
await browser.close();
EOF
